import { z } from "zod";
import { defineRoute } from "@/server/route";
import { extractionCompletion } from "@/lib/ai";
import { safeParseJson } from "@/lib/ai/json";
import { logGuardrailEvent } from "@/server/guardrails/events";
import { MEMORY_SYSTEM } from "@/lib/ai/prompts";
import { assemble } from "@/lib/ai/prompts/assemble";

export const dynamic = "force-dynamic";

const BodySchema = z.object({
  messages: z
    .array(
      z.object({
        role: z.enum(["user", "assistant", "system"]),
        content: z.string().min(1).max(8000),
      }),
    )
    .min(1)
    .max(60),
  current: z
    .object({
      brandName: z.string().max(200).optional(),
      oneLiner: z.string().max(400).optional(),
      knownInsights: z.array(z.string().max(400)).max(50).optional(),
      knownCompetitors: z.array(z.string().max(200)).max(50).optional(),
      knownTriggers: z.array(z.string().max(400)).max(50).optional(),
      knownObjections: z.array(z.string().max(400)).max(50).optional(),
      knownFeedback: z.array(z.string().max(400)).max(50).optional(),
    })
    .optional(),
});

const MAX_TRANSCRIPT_CHARS = 12_000;

const EMPTY = {
  insights: [],
  competitors: [],
  triggerSignals: [],
  objectionSignals: [],
  feedbackSources: [],
};

const MEMORY_TOOL = {
  type: "function" as const,
  function: {
    name: "save_memory",
    description: "Persist durable memory extracted from the chat.",
    parameters: {
      type: "object",
      properties: {
        insights: {
          type: "array",
          items: {
            type: "object",
            properties: { title: { type: "string" }, body: { type: "string" } },
            required: ["title", "body"],
          },
        },
        competitors: {
          type: "array",
          items: {
            type: "object",
            properties: {
              name: { type: "string" },
              url: { type: "string" },
              positioning: { type: "string" },
              strengths: { type: "string" },
              weaknesses: { type: "string" },
              notes: { type: "string" },
            },
            required: ["name"],
          },
        },
        triggerSignals: {
          type: "array",
          items: {
            type: "object",
            properties: { text: { type: "string" }, sourceLabel: { type: "string" } },
            required: ["text"],
          },
        },
        objectionSignals: {
          type: "array",
          items: {
            type: "object",
            properties: { text: { type: "string" }, sourceLabel: { type: "string" } },
            required: ["text"],
          },
        },
        feedbackSources: {
          type: "array",
          items: {
            type: "object",
            properties: { text: { type: "string" }, sourceLabel: { type: "string" } },
            required: ["text"],
          },
        },
        brand: {
          type: "object",
          properties: {
            brandName: { type: "string" },
            oneLiner: { type: "string" },
            voice: { type: "string" },
            audience: { type: "string" },
            uniqueValueProp: { type: "string" },
            mission: { type: "string" },
            vision: { type: "string" },
            positioning: { type: "string" },
            doRules: { type: "string" },
            dontRules: { type: "string" },
          },
        },
      },
      required: [
        "insights",
        "competitors",
        "triggerSignals",
        "objectionSignals",
        "feedbackSources",
      ],
    },
  },
};

export const POST = defineRoute({
  name: "memory-extract",
  auth: "user",
  body: BodySchema,
  // Gemini tool call over up to 12k chars of transcript.
  rateLimit: "generate",
  handler: async ({ body }) => {
    // Keep the NEWEST 12k chars: the newest turns are the ones not yet extracted
    // (slicing from the front re-read old turns and dropped the new facts).
    const fullTranscript = body.messages
      .map((m) => `${m.role.toUpperCase()}: ${m.content}`)
      .join("\n\n");
    const transcript =
      fullTranscript.length > MAX_TRANSCRIPT_CHARS
        ? fullTranscript.slice(fullTranscript.length - MAX_TRANSCRIPT_CHARS)
        : fullTranscript;

    const known = body.current ?? {};
    const knownBlock = assemble([
      {
        body: `Brand: ${known.brandName ?? "(unknown)"}${known.oneLiner ? ` — ${known.oneLiner}` : ""}`,
      },
      { label: "Known insights", body: known.knownInsights?.slice(0, 20).join("; ") },
      { label: "Known competitors", body: known.knownCompetitors?.slice(0, 15).join("; ") },
      { label: "Known triggers", body: known.knownTriggers?.slice(0, 15).join("; ") },
      { label: "Known objections", body: known.knownObjections?.slice(0, 15).join("; ") },
      { label: "Known feedback", body: known.knownFeedback?.slice(0, 15).join("; ") },
    ]);

    const json: any = await extractionCompletion({
      route: "memory-extract",
      messages: [
        {
          role: "system",
          content: `${MEMORY_SYSTEM}\n\nAnswer by calling the \`save_memory\` tool.`,
        },
        { role: "user", content: `${knownBlock}\n\n## Transcript\n${transcript}` },
      ],
      // tool_choice stays "auto" (forced tool use is rejected by Claude Opus 5.5).
      tools: [MEMORY_TOOL],
      max_tokens: 2000,
    });
    const args = json?.choices?.[0]?.message?.tool_calls?.[0]?.function?.arguments ?? "";
    // Usage is metered in the gateway. An extraction the model did not return
    // (or returned unparseable) is recorded, not silently read as "nothing new".
    const parsed = args ? safeParseJson<typeof EMPTY | null>(args, null) : null;
    if (!parsed) {
      logGuardrailEvent({
        kind: "parse_failure",
        severity: "warn",
        route: "memory-extract",
        detail: { toolCallReturned: Boolean(args), truncated: json?._truncated === true },
      });
      return EMPTY;
    }
    return parsed;
  },
});
